@Override
public String store(MultipartFile file) {
    if (file == null || file.isEmpty()) {
        return null;
    }

    if (file.getSize() > maxFileSize) {
        throw new BadRequestException("File size exceeds maximum allowed size");
    }

    String contentType = file.getContentType();
    if (contentType == null || !allowedTypes.contains(contentType)) {
        throw new BadRequestException("File type not allowed: " + contentType);
    }

    try {
        String extension = getExtension(contentType);
        String file_name = UUID.randomUUID() + extension;
        Path filePath = resolveWithinUploadDir(file_name);
        if (filePath == null) {
            throw new BadRequestException("Invalid file path");
        }

        Files.write(filePath, file.getBytes());

        log.info("File stored: {}", file_name);
        return urlPrefix + file_name;
    } catch (IOException e) {
        throw new InternalServerException("Failed to store file", e);
    }
}
